import { BaseApi } from './base.api';
import { SSOUserAccountCredentialsRepresentation } from '../model';

/**
 * IntegrationSSOApi service.
 */
export class IntegrationSSOApi extends BaseApi {
    /**
     * Get account information
     * @param repositoryId repositoryId
     * @return Promise<SSOUserAccountCredentialsRepresentation>
     */
    getAccountInformation(repositoryId: string): Promise<SSOUserAccountCredentialsRepresentation> {
        const pathParams = {
            repositoryId
        };

        return this.get({
            path: '/api/enterprise/integration/sso/{repositoryId}/account',
            pathParams
        });
    }
}
